--
-- Table structure for `posters`
--

DROP TABLE IF EXISTS `posters`;
CREATE TABLE `posters` (
  `id` int NOT NULL AUTO_INCREMENT,
  `city` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `image_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT (now()),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_posters_city` (`city`),
  KEY `ix_posters_id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `posters`
--
INSERT INTO `posters` VALUES (15,'Краснодар','КРАСНОДАР  \r\n\r\nНашумевшая трансформационная игра для осознанного знакомства \r\n💓За Любовь💓\r\nС Ксенией Душановой!\r\n\r\n💛 Если вы готовы построить осознанные отношения из Любви\r\n💛Если вы в отношениях и готовы перейти на следующий уровень близости\r\n💛Если вы хотите разобраться,  увидеть истину и деструктивные патерны о себе в отношениях.\r\n\r\n22 октября\r\n⏱️ 17:17\r\nОтель \"Конгресс\" \r\n🗺️ул. им П. М. Гаврилова, 1А\r\n\r\n🫶 Узнаем то, чего не знаем и куда страшно заглянуть одному\r\n🫶Познакомимся с новыми людьми, совпадающими по ценностям\r\n🫶 В душевной и непринуждённой обстановке увидим, то чего раньше не замечали. \r\n\r\nСтоимость игры от 💎 1 111₽ \r\nПо сердцу и полученной ценности.\r\n\r\nИгра проходит в камерной, уютной обстановке, до 12 человек! \r\n\r\nУспевай забронировать свое место 🥰','https://i.postimg.cc/2yQM28ZH/2025-10-19-14-18-41.png','2025-10-19 12:37:32','2025-10-22 15:26:42');
INSERT INTO `posters` VALUES (16,'Москва','2️⃣4️⃣ октября, пятница\r\nв 1️⃣7️⃣:1️⃣7️⃣\r\n📍\"Белый лист\" антикафе-коворкинг\r\nм.Добрынинская\r\n\r\nТрансформационная игра для\r\n    осознанного знакомства \r\n      💫✨За💓Любовь✨💫\r\n\r\nС Евгением и Александрой, нашедших свою любовь через игру 🙌🏻\r\n\r\n⭐️ Поиграем в трансформационную игру \"За Любовь\" для тех, кто готов принять осознанные, здоровые отношения в свою реальность.\r\n💫 Познакомимся с интересными людьми, совпадающими по ценностям.\r\n💫 Восхитительно проведем время с ви́дением неожиданной правды о себе и новыми осознаниями.\r\n\r\nУчастие в игре 1555₽!!! \r\nПри желании отблагодарите по сердцу и отклику ! \r\nСтоимость присутствия в коворкинге (от 750₽, листовой чай и печеньки без лимита).\r\n➰➰➰➰➰➰➰➰\r\n\r\nКоличество мест ограничено \r\nпо специфике игры\r\nВсего 1️⃣2️⃣ участников 💛\r\n\r\n✅Для участия, пожалуйста, зарегистрируйтесь 👉🏻в боте (https://t.me/forlove2025_bot?start=490370971) \r\n(календарь любви в подарок)\r\n\r\n📝и напишите Евгению Мельникову\r\n \"Хочу осознанно играть (https://t.me/MelnikovMiracle)\"','https://i.postimg.cc/xdB9vNng/photo-2025-10-21-08-48-28.jpg','2025-10-21 06:50:19',NULL);
INSERT INTO `posters` VALUES (17,'Ростов','❣️Трансформационная игра «ЗА ЛЮБОВЬ» для осознанного знакомства.\r\n\r\n25 октября в 12 00\r\nКафе «Кирпичик»\r\nУл . Седова 5\r\n\r\n❣️Для тех, кому важно создать осознанные отношения с собой, с партнером, с деньгами, с миром. \r\n\r\n❣️Кто готов увидеть свои неработающие стратегии и усилить себя. \r\nУвидеть, что тормозит, забирает энергию и уверенность. \r\n\r\n❣️Восхитительно проведаем время с пользой для себя и новыми осознаниями! \r\n\r\nВедет игру : основатель клуба знакомств в Москве и школы отношений ОЛЬГА КОВАЛЬСКАЯ\r\n\r\n❣️Рекомендуемая оплата за игру 2500 рублей.\r\n\r\n❣️Отблагодарите по сердцу и отклику!\r\n\r\nПредварительная запись по номеру телефона на ватсап \r\n89381132030 Елена','https://i.postimg.cc/8PPT7t2B/photo-2025-10-23-16-26-54.jpg','2025-10-23 14:34:05',NULL);


--
-- Table structure for `products`
