  `pay_metadata_id` int DEFAULT NULL,
  `sent_3d` tinyint(1) NOT NULL,
  `sent_1d` tinyint(1) NOT NULL,
  `sent_expired` tinyint(1) NOT NULL,
  `created_at` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notice_v2_user_pay` (`user_id`,`pay_metadata_id`),
  KEY `ix_subscription_notices_v2_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=906 DEFAULT CHARSET=utf8mb3;

