DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tg_id` bigint NOT NULL,
  `username` varchar(255) DEFAULT NULL,
  `full_name` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `balance` float NOT NULL,
  `inner_balance` float NOT NULL,
  `has_ended` tinyint(1) NOT NULL,
  `ref` bigint DEFAULT NULL,
  `ref_level` int NOT NULL,
  `created_at` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_tg_id` (`tg_id`),
  KEY `ix_users_tg_id` (`tg_id`),
  KEY `ix_users_ref` (`ref`)
) ENGINE=InnoDB AUTO_INCREMENT=863 DEFAULT CHARSET=utf8mb3;

